INSERT INTO `SiteContent` (`key`, `value`, `updatedAt`) VALUES ('about', '{"eyebrow":"Over onsttt","title":"Kwaliteit, innovatie en ontwikkeling. ALRA werkt graag met u samen aan de duurzaamheid van morgen!","description":"Kwaliteit, innovatie en ontwikkeling. ALRA werkt graag met u samen aan de duurzaamheid van morgen! Deskundig en vriendelijk.","image":"https://aldraled2-api-production-ebc5.up.railway.app/uploads/251dfc70-37c4-4476-99b8-a0f4fa428561.jpeg","stats":[{"label":"cdd","value":"2751"}],"values":[{"icon":"â­","title":"Kwaliteit","text":"Wij staan voor kwaliteit."}],"timelineTitle":"Onze geschiedenis","timeline":[{"year":"2014","label":"Oprichting"}]}', 'Tue Jul 28 2026 14:42:51 GMT+0200 (Midden-Europese zomertijd)');
