
DROP TABLE IF EXISTS `AnalyticsEvent`;
CREATE TABLE `AnalyticsEvent` (
  `id` varchar(36) NOT NULL,
  `visitId` varchar(36) NOT NULL,
  `type` enum('click','view','form_submit','purchase','add_to_cart','remove_from_cart','checkout_start','checkout_complete','error') NOT NULL,
  `category` varchar(100) DEFAULT NULL,
  `action` varchar(100) DEFAULT NULL,
  `label` text,
  `value` double DEFAULT NULL,
  `metadata` text,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `AnalyticsEvent_visitId_idx` (`visitId`),
  CONSTRAINT `AnalyticsEvent_visitId_Visit_id_fk` FOREIGN KEY (`visitId`) REFERENCES `Visit` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `Category`;
CREATE TABLE `Category` (
  `id` varchar(36) NOT NULL,
  `name` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `description` text,
  `imageUrl` varchar(512) DEFAULT NULL,
  `sortOrder` int NOT NULL DEFAULT '0',
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `Category_name_unique` (`name`),
  UNIQUE KEY `Category_slug_unique` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `CustomerGroup`;
CREATE TABLE `CustomerGroup` (
  `id` varchar(36) NOT NULL,
  `name` varchar(255) NOT NULL,
  `discountPercent` double NOT NULL DEFAULT '0',
  `vatReverseCharge` int NOT NULL DEFAULT '0',
  `netPrices` int NOT NULL DEFAULT '1',
  `createdAt` timestamp NOT NULL DEFAULT (now()),
  `updatedAt` timestamp NOT NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `CustomerGroup_name_unique` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `DiscountCode`;
CREATE TABLE `DiscountCode` (
  `id` varchar(36) NOT NULL,
  `code` varchar(50) NOT NULL,
  `type` enum('PERCENTAGE','FIXED') NOT NULL DEFAULT 'PERCENTAGE',
  `value` double NOT NULL,
  `minOrderAmount` double NOT NULL DEFAULT '0',
  `startDate` timestamp NULL DEFAULT NULL,
  `endDate` timestamp NULL DEFAULT NULL,
  `usageLimit` int DEFAULT NULL,
  `usageCount` int NOT NULL DEFAULT '0',
  `active` int NOT NULL DEFAULT '1',
  `createdAt` timestamp NOT NULL DEFAULT (now()),
  PRIMARY KEY (`id`),
  UNIQUE KEY `DiscountCode_code_unique` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `Notification`;
CREATE TABLE `Notification` (
  `id` varchar(36) NOT NULL,
  `type` varchar(50) NOT NULL,
  `title` varchar(255) NOT NULL,
  `message` text NOT NULL,
  `link` varchar(512) DEFAULT NULL,
  `read` int NOT NULL DEFAULT '0',
  `createdAt` timestamp NOT NULL DEFAULT (now()),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `Order`;
CREATE TABLE `Order` (
  `id` varchar(36) NOT NULL,
  `userId` varchar(36) NOT NULL,
  `total` double NOT NULL,
  `discountCodeId` varchar(36) DEFAULT NULL,
  `discountAmount` double NOT NULL DEFAULT '0',
  `status` enum('PENDING','PROCESSING','SHIPPED','DELIVERED','CANCELLED') NOT NULL DEFAULT 'PENDING',
  `createdAt` timestamp NOT NULL DEFAULT (now()),
  `updatedAt` timestamp NOT NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
  `shippingName` varchar(255) DEFAULT NULL,
  `shippingCompany` varchar(255) DEFAULT NULL,
  `shippingAddress` varchar(255) DEFAULT NULL,
  `shippingPostcode` varchar(20) DEFAULT NULL,
  `shippingCity` varchar(100) DEFAULT NULL,
  `shippingCountry` varchar(2) DEFAULT 'NL',
  `shippingPhone` varchar(50) DEFAULT NULL,
  `shippingMethod` varchar(100) DEFAULT NULL,
  `shippingCost` double NOT NULL DEFAULT '0',
  `trackingNumber` varchar(255) DEFAULT NULL,
  `trackingUrl` varchar(512) DEFAULT NULL,
  `sendcloudShipmentId` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `Order_userId_User_id_fk` (`userId`),
  KEY `Order_discountCodeId_DiscountCode_id_fk` (`discountCodeId`),
  CONSTRAINT `Order_discountCodeId_DiscountCode_id_fk` FOREIGN KEY (`discountCodeId`) REFERENCES `DiscountCode` (`id`),
  CONSTRAINT `Order_userId_User_id_fk` FOREIGN KEY (`userId`) REFERENCES `User` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `OrderItem`;
CREATE TABLE `OrderItem` (
  `id` varchar(36) NOT NULL,
  `orderId` varchar(36) NOT NULL,
  `productId` varchar(36) DEFAULT NULL,
  `quantity` int NOT NULL,
  `price` double NOT NULL,
  PRIMARY KEY (`id`),
  KEY `OrderItem_orderId_Order_id_fk` (`orderId`),
  KEY `OrderItem_productId_Product_id_fk` (`productId`),
  CONSTRAINT `OrderItem_orderId_Order_id_fk` FOREIGN KEY (`orderId`) REFERENCES `Order` (`id`),
  CONSTRAINT `OrderItem_productId_Product_id_fk` FOREIGN KEY (`productId`) REFERENCES `Product` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `PageView`;
CREATE TABLE `PageView` (
  `id` varchar(36) NOT NULL,
  `visitId` varchar(36) NOT NULL,
  `url` text NOT NULL,
  `title` text,
  `referrer` text,
  `timeOnPage` int DEFAULT '0',
  `scrollDepth` int DEFAULT '0',
  `isExit` int NOT NULL DEFAULT '0',
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `PageView_visitId_idx` (`visitId`),
  CONSTRAINT `PageView_visitId_Visit_id_fk` FOREIGN KEY (`visitId`) REFERENCES `Visit` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `Payment`;
CREATE TABLE `Payment` (
  `id` varchar(36) NOT NULL,
  `orderId` varchar(36) NOT NULL,
  `molliePaymentId` varchar(255) DEFAULT NULL,
  `molliePaymentUrl` varchar(512) DEFAULT NULL,
  `amount` double NOT NULL,
  `currency` varchar(3) NOT NULL DEFAULT 'EUR',
  `method` varchar(50) DEFAULT NULL,
  `status` enum('PENDING','OPEN','CANCELLED','EXPIRED','FAILED','PAID') NOT NULL DEFAULT 'PENDING',
  `paidAt` timestamp NULL DEFAULT NULL,
  `metadata` text,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `Payment_orderId_index` (`orderId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `Product`;
CREATE TABLE `Product` (
  `id` varchar(36) NOT NULL,
  `name` varchar(255) NOT NULL,
  `description` text,
  `price` double NOT NULL,
  `stock` int NOT NULL DEFAULT '0',
  `imageUrl` varchar(512) DEFAULT NULL,
  `category` varchar(255) DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT (now()),
  `updatedAt` timestamp NOT NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
  `specs` text,
  `categoryId` varchar(36) DEFAULT NULL,
  `pdfUrl` varchar(512) DEFAULT NULL,
  `videoUrl` varchar(512) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `Product_categoryId_Category_id_fk` (`categoryId`),
  CONSTRAINT `Product_categoryId_Category_id_fk` FOREIGN KEY (`categoryId`) REFERENCES `Category` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
