DROP TABLE IF EXISTS `ProductImage`;
CREATE TABLE `ProductImage` (
  `id` varchar(36) NOT NULL,
  `productId` varchar(36) NOT NULL,
  `url` varchar(512) NOT NULL,
  `sortOrder` int NOT NULL DEFAULT '0',
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ProductImage_productId_idx` (`productId`),
  CONSTRAINT `ProductImage_productId_Product_id_fk` FOREIGN KEY (`productId`) REFERENCES `Product` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `ProductPriceTier`;
CREATE TABLE `ProductPriceTier` (
  `id` varchar(36) NOT NULL,
  `productId` varchar(36) NOT NULL,
  `minQty` int NOT NULL,
  `price` double NOT NULL,
  `createdAt` timestamp NOT NULL DEFAULT (now()),
  PRIMARY KEY (`id`),
  KEY `ProductPriceTier_productId_Product_id_fk` (`productId`),
  CONSTRAINT `ProductPriceTier_productId_Product_id_fk` FOREIGN KEY (`productId`) REFERENCES `Product` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `ProductRelation`;
CREATE TABLE `ProductRelation` (
  `id` varchar(36) NOT NULL,
  `productId` varchar(36) NOT NULL,
  `relatedProductId` varchar(36) NOT NULL,
  `type` enum('UPSELL','CROSS_SELL','RELATED') NOT NULL DEFAULT 'RELATED',
  PRIMARY KEY (`id`),
  KEY `ProductRelation_productId_Product_id_fk` (`productId`),
  KEY `ProductRelation_relatedProductId_Product_id_fk` (`relatedProductId`),
  CONSTRAINT `ProductRelation_productId_Product_id_fk` FOREIGN KEY (`productId`) REFERENCES `Product` (`id`) ON DELETE CASCADE,
  CONSTRAINT `ProductRelation_relatedProductId_Product_id_fk` FOREIGN KEY (`relatedProductId`) REFERENCES `Product` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `Quote`;
CREATE TABLE `Quote` (
  `id` varchar(36) NOT NULL,
  `name` varchar(255) NOT NULL,
  `email` varchar(255) NOT NULL,
  `phone` varchar(50) DEFAULT NULL,
  `company` varchar(255) DEFAULT NULL,
  `message` text,
  `items` text NOT NULL,
  `total` double NOT NULL DEFAULT '0',
  `status` enum('NEW','VIEWED','CONTACTED','CONVERTED','ARCHIVED') NOT NULL DEFAULT 'NEW',
  `createdAt` timestamp NOT NULL DEFAULT (now()),
  `updatedAt` timestamp NOT NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `Rma`;
CREATE TABLE `Rma` (
  `id` varchar(36) NOT NULL,
  `orderId` varchar(36) NOT NULL,
  `userId` varchar(36) NOT NULL,
  `status` enum('REQUESTED','APPROVED','REJECTED','RECEIVED','REFUNDED','CLOSED') NOT NULL DEFAULT 'REQUESTED',
  `reason` text,
  `message` text,
  `adminNote` text,
  `createdAt` timestamp NOT NULL DEFAULT (now()),
  `updatedAt` timestamp NOT NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `Rma_orderId_Order_id_fk` (`orderId`),
  KEY `Rma_userId_User_id_fk` (`userId`),
  CONSTRAINT `Rma_orderId_Order_id_fk` FOREIGN KEY (`orderId`) REFERENCES `Order` (`id`),
  CONSTRAINT `Rma_userId_User_id_fk` FOREIGN KEY (`userId`) REFERENCES `User` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `RmaItem`;
CREATE TABLE `RmaItem` (
  `id` varchar(36) NOT NULL,
  `rmaId` varchar(36) NOT NULL,
  `orderItemId` varchar(36) NOT NULL,
  `quantity` int NOT NULL,
  `createdAt` timestamp NOT NULL DEFAULT (now()),
  PRIMARY KEY (`id`),
  KEY `RmaItem_rmaId_Rma_id_fk` (`rmaId`),
  KEY `RmaItem_orderItemId_OrderItem_id_fk` (`orderItemId`),
  CONSTRAINT `RmaItem_orderItemId_OrderItem_id_fk` FOREIGN KEY (`orderItemId`) REFERENCES `OrderItem` (`id`),
  CONSTRAINT `RmaItem_rmaId_Rma_id_fk` FOREIGN KEY (`rmaId`) REFERENCES `Rma` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `SendcloudConfig`;
CREATE TABLE `SendcloudConfig` (
  `key` varchar(255) NOT NULL,
  `value` text NOT NULL,
  `updatedAt` timestamp NOT NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `SiteContent`;
CREATE TABLE `SiteContent` (
  `key` varchar(255) NOT NULL,
  `value` text NOT NULL,
  `updatedAt` timestamp NOT NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `SnelstartConfig`;
CREATE TABLE `SnelstartConfig` (
  `id` varchar(36) NOT NULL,
  `apiKey` varchar(255) DEFAULT NULL,
  `clientKey` varchar(255) DEFAULT NULL,
  `ledgerNumberSales` varchar(50) DEFAULT NULL,
  `ledgerNumberVat21` varchar(50) DEFAULT NULL,
  `ledgerNumberVat9` varchar(50) DEFAULT NULL,
  `ledgerNumberVat0` varchar(50) DEFAULT NULL,
  `ledgerNumberShipping` varchar(50) DEFAULT NULL,
  `snelstartVatCode21` varchar(50) DEFAULT NULL,
  `snelstartVatCode9` varchar(50) DEFAULT NULL,
  `snelstartVatCode0` varchar(50) DEFAULT NULL,
  `enabled` int NOT NULL DEFAULT '0',
  `updatedAt` timestamp NOT NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `SnelstartLedger`;
CREATE TABLE `SnelstartLedger` (
  `id` varchar(36) NOT NULL,
  `code` varchar(50) NOT NULL,
  `name` varchar(255) NOT NULL,
  `type` enum('SALES','VAT','SHIPPING','OTHER') NOT NULL DEFAULT 'OTHER',
  `createdAt` timestamp NOT NULL DEFAULT (now()),
  PRIMARY KEY (`id`),
  UNIQUE KEY `SnelstartLedger_code_unique` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `SnelstartSyncLog`;
CREATE TABLE `SnelstartSyncLog` (
  `id` varchar(36) NOT NULL,
  `orderId` varchar(36) NOT NULL,
  `status` enum('SUCCESS','FAILED') NOT NULL,
  `errorMessage` text,
  `syncedAt` timestamp NOT NULL DEFAULT (now()),
  PRIMARY KEY (`id`),
  KEY `SnelstartSyncLog_orderId_Order_id_fk` (`orderId`),
  CONSTRAINT `SnelstartSyncLog_orderId_Order_id_fk` FOREIGN KEY (`orderId`) REFERENCES `Order` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `SystemLog`;
CREATE TABLE `SystemLog` (
  `id` varchar(36) NOT NULL,
  `type` varchar(50) NOT NULL,
  `level` enum('INFO','WARN','ERROR') NOT NULL DEFAULT 'INFO',
  `source` varchar(100) NOT NULL,
  `message` text NOT NULL,
  `details` text,
  `orderId` varchar(36) DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT (now()),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
