DROP TABLE IF EXISTS `User`;
CREATE TABLE `User` (
  `id` varchar(36) NOT NULL,
  `email` varchar(255) NOT NULL,
  `password` varchar(255) NOT NULL,
  `name` varchar(255) DEFAULT NULL,
  `role` enum('USER','ADMIN') NOT NULL DEFAULT 'USER',
  `customerGroupId` varchar(36) DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT (now()),
  `updatedAt` timestamp NOT NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `User_email_unique` (`email`),
  KEY `User_customerGroupId_CustomerGroup_id_fk` (`customerGroupId`),
  CONSTRAINT `User_customerGroupId_CustomerGroup_id_fk` FOREIGN KEY (`customerGroupId`) REFERENCES `CustomerGroup` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `Visit`;
CREATE TABLE `Visit` (
  `id` varchar(36) NOT NULL,
  `sessionId` varchar(255) NOT NULL,
  `userAgent` text,
  `ip` varchar(45) DEFAULT NULL,
  `referrer` text,
  `utmSource` varchar(255) DEFAULT NULL,
  `utmMedium` varchar(255) DEFAULT NULL,
  `utmCampaign` varchar(255) DEFAULT NULL,
  `country` varchar(2) DEFAULT NULL,
  `city` varchar(100) DEFAULT NULL,
  `device` varchar(50) DEFAULT NULL,
  `browser` varchar(50) DEFAULT NULL,
  `os` varchar(50) DEFAULT NULL,
  `isNewVisitor` int NOT NULL DEFAULT '1',
  `landingPage` text,
  `exitPage` text,
  `duration` int DEFAULT '0',
  `pageViews` int NOT NULL DEFAULT '0',
  `converted` int NOT NULL DEFAULT '0',
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
